const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/coordination_issues/templates/picker',
  qs: {search: 'MEP', page: 'SOME_INTEGER_VALUE', per_page: 'SOME_INTEGER_VALUE'},
  headers: {'Procore-Company-Id': 'SOME_STRING_VALUE'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/coordination_issues/templates/picker?search=MEP&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

